// Code generated by `cargo run -p codegen` — DO NOT EDIT
// Quantity: Magnetization

#![cfg(feature = "electrical")]
#![allow(
    clippy::excessive_precision,
    clippy::unreadable_literal,
    clippy::double_parens,
    unused_parens
)]

use super::{assert_close, check_fixed, check_fixed_rescale, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use unitsnet_rs::*;

#[test]
fn amperes_per_meter() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(
            Magnetization::from_amperes_per_meter(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x;
        assert_close(
            Magnetization::from_base(base).as_amperes_per_meter(),
            back,
            F64_TOL,
        );
        assert_close(
            Magnetization::from_amperes_per_meter(v).as_amperes_per_meter(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            Magnetization::from_amperes_per_meter(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Magnetization::from_base(base as f32).as_amperes_per_meter() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn fixed_units() {
    check_fixed::<unit::magnetization::AmperePerMeter>();
    check_fixed_rescale::<unit::magnetization::AmperePerMeter>();
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Magnetization::new(v, MagnetizationUnit::AmperePerMeter),
        Magnetization::from_amperes_per_meter(v)
    );
    assert_eq!(
        Magnetization::from_base(v).convert_to(MagnetizationUnit::AmperePerMeter),
        Magnetization::from_base(v).as_amperes_per_meter()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Magnetization; 1] = [Magnetization::const_new(
        1234.5,
        MagnetizationUnit::AmperePerMeter,
    )];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(MagnetizationUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Magnetization::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in MagnetizationUnit::ALL {
            assert_eq!(
                Magnetization::const_new(v, unit).as_base().to_bits(),
                Magnetization::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Magnetization::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            Magnetization::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in MagnetizationUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Magnetization::from_base(0.0).auto_unit().unit,
        MagnetizationUnit::AmperePerMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "A/m".parse::<MagnetizationUnit>(),
        Ok(MagnetizationUnit::AmperePerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "A/m").parse::<Magnetization>(),
        Ok(Magnetization::new(2.5, MagnetizationUnit::AmperePerMeter))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Magnetization>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn parse_every_name() {
    assert_eq!(
        MagnetizationUnit::from_name("amperepermeter"),
        Some(MagnetizationUnit::AmperePerMeter)
    );
    assert_eq!(
        MagnetizationUnit::from_name("ampere per meter"),
        Some(MagnetizationUnit::AmperePerMeter)
    );
    assert_eq!(
        MagnetizationUnit::from_name("AMPERE PER METER"),
        Some(MagnetizationUnit::AmperePerMeter)
    );
    assert_eq!(
        MagnetizationUnit::from_name("amperespermeter"),
        Some(MagnetizationUnit::AmperePerMeter)
    );
    assert_eq!(
        MagnetizationUnit::from_name("amperes per meter"),
        Some(MagnetizationUnit::AmperePerMeter)
    );
    assert_eq!(
        MagnetizationUnit::from_name("AMPERES PER METER"),
        Some(MagnetizationUnit::AmperePerMeter)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Magnetization::from_base(6.0);
    let b = Magnetization::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Magnetization::<i64>::from_base(7);
    let b = Magnetization::<i64>::from_base(2);
    assert_eq!(a + b, Magnetization::from_base(9));
    assert_eq!(a % b, Magnetization::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<Magnetization<i64>>(),
        Magnetization::from_base(9)
    );
}
